// SPDX-License-Identifier: APACHE-2.0

pragma solidity ^0.8.20;

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IOFT, SendParam, MessagingFee, MessagingReceipt, OFTReceipt } from "@layerzerolabs/oft-evm/contracts/interfaces/IOFT.sol";
import { IERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import { OwnableOperators } from "../mixins/OwnableOperators.sol";

/**
 * @title TransactionValueHelper
 * @notice A helper contract that manages token transfers and calculates fees for OFT (Omnichain Fungible Token) operations
 * @dev This contract handles the conversion of native token fees to the underlying token using price feeds
 */
interface IPriceFeed {
    function getPriceRatioDenominator() external view returns (uint128);
    function nativeTokenPriceUSD() external view returns (uint128);
}

contract TransactionValueHelper is OwnableOperators {
    using SafeERC20 for IERC20Metadata;

    event LogSetMaxGas(uint256 maxGas);
    event LogSetPriceFactor(uint256 oldPriceFactor, uint256 newPriceFactor);
    event LogSend(
        address indexed sender,
        address indexed oft,
        uint256 amountLD,
        uint256 nativeFee,
        uint256 feeInToken,
        uint256 totalAmount
    );
    event LogExecute(
        address indexed operator,
        address indexed target,
        uint256 value,
        bytes data
    );

    // Maximum amount of native token that can be used for gas
    uint256 public maxGas;
    // Precision for native token (e.g., 1e18 for ETH)
    uint256 public constant NATIVE_PRECISION = 1e18;
    // Price factor for fee calculation (12000/10000 = 1.2x multiplier)
    uint256 public priceFactor;
    uint256 constant PRICE_FACTOR_PRECISION = 10_000;

    // Token precision based on decimals
    uint256 immutable tokenPrecision;
    // The token being managed (e.g., USDT)
    IERC20Metadata public immutable token;
    // Price feed contract to get native token price in USD
    IPriceFeed public immutable priceFeed;

    constructor(IERC20Metadata _token, IPriceFeed _priceFeed) {
        token = _token;
        tokenPrecision = 10**token.decimals();
        priceFeed = _priceFeed;
        priceFactor = 12_000; // Initialize with default 1.2x multiplier
        _initializeOwner(msg.sender);
    }

    // Allow the contract to receive native tokens
    receive() external payable {
    }

    /**
     * @notice Sets the maximum amount of native token that can be used for gas
     * @param _maxGas The maximum gas amount in native token
     */
    function setMaxGas(uint256 _maxGas) external onlyOwner {
        maxGas = _maxGas;
        emit LogSetMaxGas(_maxGas);
    }

    /**
     * @notice Executes an OFT send operation with fee calculation
     * @param _oft The OFT contract to send tokens through
     * @param _sendParam Parameters for the send operation
     * @param _fee Messaging fee for the cross-chain operation
     * @return msgReceipt The messaging receipt
     * @return oftReceipt The OFT receipt
     */
    function send(
        IOFT _oft,
        SendParam calldata _sendParam,
        MessagingFee calldata _fee
    ) external payable returns (MessagingReceipt memory msgReceipt, OFTReceipt memory oftReceipt) {
        require(msg.value == 0, "TransactionValueHelper: msg.value not zero");
        uint256 nativeAmount = address(this).balance;
        token.safeTransferFrom(msg.sender, address(this), _sendParam.amountLD);
        if (_oft.approvalRequired()) {
            token.forceApprove(address(_oft), _sendParam.amountLD);
        }
        (msgReceipt, oftReceipt) = _oft.send{value: _fee.nativeFee}(_sendParam, _fee, address(this));
        nativeAmount = nativeAmount - address(this).balance;
        require(nativeAmount <= maxGas, "TransactionValueHelper: gas limit exceeded");

        uint256 feeInToken = (priceFeed.nativeTokenPriceUSD() * nativeAmount * tokenPrecision * priceFactor) / (priceFeed.getPriceRatioDenominator() * NATIVE_PRECISION * PRICE_FACTOR_PRECISION);
        token.safeTransferFrom(msg.sender, address(this), feeInToken);

        emit LogSend(
            msg.sender,
            address(_oft),
            _sendParam.amountLD,
            _fee.nativeFee,
            feeInToken,
            _sendParam.amountLD + feeInToken
        );
    }

    /**
     * @notice Executes an arbitrary call with native token value
     * @param _to The target address
     * @param value The amount of native token to send
     * @param _data The calldata to send
     */
    function execute(address _to, uint256 value, bytes calldata _data) external onlyOperators {
        (bool success, ) = _to.call{value: value}(_data);
        require(success, "TransactionValueHelper: call failed");

        emit LogExecute(
            msg.sender,
            _to,
            value,
            _data
        );
    }

    /**
     * @notice Calculates the amount of tokens needed for a specific send operation
     * @param _sendParam Parameters for the send operation
     * @param _fee Messaging fee for the cross-chain operation
     * @return totalAmount The total amount of tokens needed (including the send amount and fee)
     */
    function quoteSend(
        SendParam calldata _sendParam,
        MessagingFee calldata _fee
    ) external view returns (uint256 totalAmount) {
        // Calculate the fee in terms of the underlying token
        uint256 feeInToken = (_fee.nativeFee * priceFeed.nativeTokenPriceUSD() * tokenPrecision * priceFactor) / 
            (priceFeed.getPriceRatioDenominator() * NATIVE_PRECISION * PRICE_FACTOR_PRECISION);

        // Total amount is the send amount plus the fee
        totalAmount = _sendParam.amountLD + feeInToken;
    }

    /**
     * @notice Updates the price factor used for fee calculations
     * @param _newPriceFactor The new price factor (e.g., 12000 for 1.2x multiplier)
     * @dev The price factor is used to add a markup to the fee calculation
     * @dev The actual multiplier is priceFactor/PRICE_FACTOR_PRECISION (e.g., 12000/10000 = 1.2x)
     */
    function setPriceFactor(uint256 _newPriceFactor) external onlyOwner {
        require(_newPriceFactor >= PRICE_FACTOR_PRECISION,
                "TransactionValueHelper: price factor must be greater than PRICE_FACTOR_PRECISION");
        uint256 oldPriceFactor = priceFactor;
        priceFactor = _newPriceFactor;
        emit LogSetPriceFactor(oldPriceFactor, _newPriceFactor);
    }
}

