// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IOAppComposer } from "@layerzerolabs/oapp-evm/contracts/oapp/interfaces/IOAppComposer.sol";
import { SendParam, IOFT, MessagingFee } from "@layerzerolabs/oft-evm/contracts/interfaces/IOFT.sol";
import { OFTComposeMsgCodec } from "@layerzerolabs/oft-evm/contracts/libs/OFTComposeMsgCodec.sol";
import { GasUSDT0Converter } from "./GasUSDT0Converter.sol";

/// @title StableComposer Contract
/// @notice The contract is intended to unwrap USDT0 into native gas tokens.
contract StableComposer is IOAppComposer {
    using SafeERC20 for IERC20;

    struct FailedMessage {
        SendParam refundSendParam;
        uint256 msgValue;
    }

    /// ----------------------------------- ERRORS -----------------------------------
    error OnlyEndpoint(address caller);
    error OnlyOFT(address oft);
    error FailedMessageNotFound(bytes32 guid);

    /// ----------------------------------- EVENTS -----------------------------------
    event FailedMessageDecode(bytes32 indexed guid, bytes32 sender, uint256 msgValue, bytes composeMessage);
    event RefundSuccessful(bytes32 indexed guid);
    event Unwrap(address indexed user, address tokenOut, uint256 amount);

    IERC20 public immutable token;
    GasUSDT0Converter public immutable wrapper;
    address public immutable endpoint;
    address public immutable oApp;

    mapping(bytes32 guid => FailedMessage) public failedMessages;

    /// @notice Constructs the StableComposer contract.
    /// @dev Initializes the contract.
    /// @param _token The address of the token
    /// @param _wrapper The address of the Wrapper
    /// @param _endpoint LayerZero Endpoint address
    /// @param _oApp The address of the OApp that is sending the composed message.
    constructor(address _token, GasUSDT0Converter _wrapper, address _endpoint, address _oApp) {
        token = IERC20(_token);
        // Approve the wrapper to allow unwraps
        token.forceApprove(address(_wrapper), type(uint256).max);
        wrapper = _wrapper;
        endpoint = _endpoint;
        oApp = _oApp;
    }

    /// @notice Handles incoming composed messages from LayerZero.
    /// @dev This method expects the encoded compose message to contain the recipient address.
    /// @param _oApp The address of the originating OApp.
    /// @param _guid The globally unique identifier of the message.
    /// @param _message The encoded message content in the format of the OFTComposeMsgCodec.
    /// @param /*Executor*/ Executor address.
    /// @param /*Executor Data*/ Additional data for checking for a specific executor.
    function lzCompose(
        address _oApp,
        bytes32 _guid,
        bytes calldata _message,
        address /*Executor*/,
        bytes calldata /*Executor Data*/
    ) external payable override {
        if (msg.sender != endpoint) revert OnlyEndpoint(msg.sender);
        if (_oApp != oApp) revert OnlyOFT(_oApp);

        // Extract the composed message from the delivered message using the MsgCodec
        bytes memory composeMsgEncoded = OFTComposeMsgCodec.composeMsg(_message);
        uint256 _amountLD = OFTComposeMsgCodec.amountLD(_message);

        /// @dev Decode message to get receiver and perform hypercore transfers, store in failedMessages if decode fails
        try this.decodeMessage(composeMsgEncoded) returns (address _receiver) {            
            // Execute the token swap by transferring the specified amount to the receiver
            wrapper.withdrawTo(_receiver, _amountLD);
            // Emit an event to log the token swap details
            emit Unwrap(_receiver, address(token), _amountLD);
        } catch {
            SendParam memory refundSendParam;
            refundSendParam.dstEid = OFTComposeMsgCodec.srcEid(_message);
            refundSendParam.to = OFTComposeMsgCodec.composeFrom(_message);
            refundSendParam.amountLD = _amountLD;

            failedMessages[_guid] = FailedMessage({ refundSendParam: refundSendParam, msgValue: msg.value });
            emit FailedMessageDecode(_guid, refundSendParam.to, msg.value, composeMsgEncoded);
        }
    }

    /**
     * @notice Decodes the compose message to extract receiver address
     * @param _composeMessage The encoded compose message
     * @return to - The receiver address
     */
    function decodeMessage(bytes calldata _composeMessage) external pure returns (address to) {
        to = abi.decode(_composeMessage, (address));
    }

    /**
     * @notice Refunds failed messages to the source chain
     * @param _guid The GUID of the failed message to refund
     */
    function refundToSrc(bytes32 _guid) external payable virtual {
        FailedMessage memory failedMessage = failedMessages[_guid];
        if (failedMessage.refundSendParam.dstEid == 0) revert FailedMessageNotFound(_guid);

        delete failedMessages[_guid];

        uint256 totalMsgValue = failedMessage.msgValue + msg.value;

        /// @dev Triggers a refund via the OFT with the refundSendParam for the ERC20 amt
        /// @dev msg.value, if any was passed is used to pay the layerzero message fee and excess refunded to tx.origin
        IOFT(oApp).send{ value: totalMsgValue }(
            failedMessage.refundSendParam,
            MessagingFee(totalMsgValue, 0),
            tx.origin
        );

        emit RefundSuccessful(_guid);
    }
}

